SELECT
	COUNT(*)
FROM
	FACILITY_STUDY
WHERE
	homepage_id = #{homepage_id}
AND	study_date = #{study_date}
AND	study_time = #{study_time}
AND	study_idx != #{study_idx}
AND	apply_status != '2'
